private let stateDirectory: URL
let safety: USBConnectionSafety
public init(stateDirectory: URL) {
    self.stateDirectory = stateDirectory
    safety = USBConnectionSafety(directory: USBConnectionSafety.canonicalDirectory)
}
// Offline tests may isolate safety state; this is not exposed to CLI callers.
init(stateDirectory: URL, safety: USBConnectionSafety) {
    self.stateDirectory = stateDirectory; self.safety = safety

@main struct EA9CLI {
    private static func variant(for command: String) -> FirmwareVariant {
        switch command {
        case "prepare-handoff-upstream", "apply-handoff-upstream": .autofocusStartupHandoff
        case "prepare-absolute-upstream", "apply-absolute-upstream": .autofocusAbsoluteUpstream
        case "prepare-bounded-upstream", "apply-bounded-upstream": .autofocusBoundedUpstream
        case "prepare-hardened-upstream", "apply-hardened-upstream": .autofocusUpstreamHardened
        case "prepare-startup", "apply-startup": .autofocusStartupDiagnostic
        case "prepare-upstream", "apply-upstream": .autofocusUpstreamBaseline
        case "prepare-af", "apply-af": .autofocusArbitratedCamera
        default: .metadataOnly

static func main() async {
    do {
        var args = Array(CommandLine.arguments.dropFirst())
        var state = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("org.openlmea9.prototype", isDirectory: true)
        if let index = args.firstIndex(of: "--state-directory"), index + 1 < args.count {
            state = URL(fileURLWithPath: args[index + 1], isDirectory: true)
            args.removeSubrange(index...index + 1)
        }
        let service = DeviceService(stateDirectory: state)
        let usage = "Startup handoff: prepare-handoff-upstream PROFILE-ID NEW.bin | apply-handoff-upstream PROFILE-ID --idle. Absolute upstream: prepare-absolute-upstream PROFILE-ID NEW.bin | apply-absolute-upstream PROFILE-ID --idle. Bounded upstream: prepare-bounded-upstream PROFILE-ID NEW.bin | apply-bounded-upstream PROFILE-ID --idle. Hardened upstream: prepare-hardened-upstream PROFILE-ID NEW.bin | apply-hardened-upstream PROFILE-ID --idle. Startup diagnostic: prepare-startup PROFILE-ID NEW.bin | apply-startup PROFILE-ID --idle. Usage: ea9ctl [--state-directory PATH] inventory | backup NEW.ea9backup --idle | apply PROFILE-ID --idle | apply-af PROFILE-ID --idle | qualify-stock --idle | verify --idle | inspect --idle | restore-stock ORIGINAL.ea9backup --idle | prepare PROFILE-ID NEW.bin | prepare-af PROFILE-ID NEW.bin | prepare-upstream PROFILE-ID NEW.bin | apply-upstream PROFILE-ID --idle"
        guard args == ["inventory"] || (args.count == 3 && ["backup","apply","apply-af","apply-upstream","apply-startup","apply-hardened-upstream","apply-bounded-upstream","apply-absolute-upstream","apply-handoff-upstream","restore-stock"].contains(args[0]) && args[2] == "--idle")
            || (args.count == 2 && ["verify","inspect","qualify-stock"].contains(args[0]) && args[1] == "--idle")
            || (args.count == 3 && ["prepare","prepare-af","prepare-upstream","prepare-startup","prepare-hardened-upstream","prepare-bounded-upstream","prepare-absolute-upstream","prepare-handoff-upstream"].contains(args[0]))
            || (args.count == 3 && args[0] == "resolve-stock-after-camera" && args[2] == "--idle") else { throw DeviceError.failure(usage + " | resolve-stock-after-camera REVIEWED.ea9backup --idle") }
        if ["prepare","prepare-af","prepare-upstream","prepare-startup","prepare-hardened-upstream","prepare-bounded-upstream","prepare-absolute-upstream","prepare-handoff-upstream"].contains(args[0]) {
            let library = try LibraryStore(directory: state).loadOrSeed()
            guard let profile = library.profiles.first(where: { $0.id == args[1] }) else { throw DeviceError.failure("Unknown lens profile.") }
            let data = try FirmwareImageBuilder.prepare(profile: profile, variant: variant(for: args[0]))
            try data.write(to: URL(fileURLWithPath: args[2]), options: .withoutOverwriting)
            print("Prepared application image: \(data.count) bytes. No USB reports sent.")
            return
        }
        let devices = try await service.inventory()
